package shop.ultimatesmp.crates;
import java.util.*;import org.bukkit.configuration.file.YamlConfiguration;
final class CrateCodec {
 static String encode(Crate c){var y=new YamlConfiguration();y.set("id",c.id());y.set("name",c.name());y.set("revision",c.revision());var label=c.label();y.set("label.text",label.text());y.set("label.color",label.color());y.set("label.size",label.size());y.set("label.height",label.height());y.set("label.visible",label.visible());for(int i=0;i<c.rewards().size();i++){var r=c.rewards().get(i);String p="rewards."+i;y.set(p+".item",r.item());y.set(p+".weight",r.weight());y.set(p+".rarity",r.rarity().name());y.set(p+".chance",r.chance());}return y.saveToString();}
 static Crate decode(String payload)throws Exception{var y=new YamlConfiguration();y.loadFromString(payload);var list=new ArrayList<Crate.Reward>();var section=y.getConfigurationSection("rewards");if(section!=null)for(String k:section.getKeys(false)){String p="rewards."+k;list.add(new Crate.Reward(y.getItemStack(p+".item"),y.getInt(p+".weight"),LootPolicy.Rarity.parse(y.getString(p+".rarity","LEGACY")),y.contains(p+".chance")?y.getDouble(p+".chance"):null));}LabelStyle defaults=LabelStyle.defaults();var label=new LabelStyle(y.getString("label.text",defaults.text()),y.getString("label.color",defaults.color()),(float)y.getDouble("label.size",defaults.size()),y.getDouble("label.height",defaults.height()),y.getBoolean("label.visible",true));return new Crate(y.getString("id"),y.getString("name"),y.getLong("revision"),list,label);}
}

